// §10.4 Node 1 — Order Confirmation trigger
// The customer replied 'CONFIRM', 'yes', etc. → classified as ORDER_CONFIRMATION
// We need to reconstruct the pending order from the last bulk-pricing conversation.
// Since we logged the pricing breakdown in conversations, we fetch the last outbound message
// to extract the order details.

const ctx = $input.item.json;

return [{
  json: {
    business_id:  ctx.business_id,
    business_name: ctx.business_name,
    phoneNumber:  ctx.phoneNumber,
    chatId:       ctx.chatId,
    language:     ctx.language,
    messageText:  ctx.messageText
  }
}];

const ctx = $('Prepare Extractor Prompt').item.json;
const rawResponse = $input.item.json.text ?? $input.item.json.response ?? '{}';

let orderData = { items: [], discount_applied: 0 };
try {
  const cleaned = rawResponse.replace(/\r\n/g, '\n').replace(/\n/g, '').replace(/```json/g, '').replace(/```/g, '').trim();
  orderData = JSON.parse(cleaned);
  if (Array.isArray(orderData)) orderData = { items: orderData, discount_applied: 0 };
} catch (e) {
  orderData = { items: [{ product_name: 'Unknown - parse failed', qty: 1, unit_price: 0 }], discount_applied: 0 };
}

let total = 0;
for (let item of orderData.items) {
  total += (item.qty || 0) * (item.unit_price || 0);
}
total -= (orderData.discount_applied || 0);
const delivery_charge = 1.17; // Equivalent to ~350 LKR
total += delivery_charge;

return [{
  json: {
    ...ctx,
    items:            JSON.stringify(orderData.items),
    total_price:      parseFloat(total.toFixed(2)),
    discount_applied: parseFloat((orderData.discount_applied || 0).toFixed(2)),
    status:           'confirmed'
  }
}];

